const MAX_ARTICLES = 8;
const MAX_ARTICLES_PER_SOURCE = 3;

function getArticle(item) {
  return item.json;
}

function hasId(article) {
  return Boolean(article.id);
}

function trim(text) {
  return text.trim();
}

function parseInterests(interests) {
  return (interests || '').split(',').map(trim).filter(Boolean);
}

function countSharedCategories(article) {
  const categories = (article.categories || '').split(',');
  let count = 0;
  for (const category of categories) {
    if (userInterests.includes(category)) {
      count++;
    }
  }
  return count;
}

function withMatchCount(article) {
  return { ...article, matches: countSharedCategories(article) };
}

function isRelevant(article) {
  return article.matches > 0;
}

function byRelevanceThenRecency(first, second) {
  return second.matches - first.matches || new Date(second.published_at) - new Date(first.published_at);
}

function limitPerSource(articles, maxPerSource, maxTotal) {
  const countBySource = {};
  const selected = [];
  for (const article of articles) {
    countBySource[article.source] = (countBySource[article.source] || 0) + 1;
    if (countBySource[article.source] <= maxPerSource) {
      selected.push(article);
    }
    if (selected.length === maxTotal) {
      break;
    }
  }
  return selected;
}

function toNewsletterArticle(article) {
  const { id, title, url, source, summary, categories, published_at } = article;
  return { id, title, url, source, summary, categories, published_at };
}

const user = $('Get user').first().json;
const userInterests = parseInterests(user.interests);
const rankedArticles = $input.all().map(getArticle).filter(hasId).map(withMatchCount).filter(isRelevant).sort(byRelevanceThenRecency);
const articles = limitPerSource(rankedArticles, MAX_ARTICLES_PER_SOURCE, MAX_ARTICLES).map(toNewsletterArticle);

return [{ json: { user, articles } }];

const BRAND_NAME = 'NewsLetter';
const SUPPORTED_LANGUAGES = ['fr', 'en'];
const DEFAULT_LANGUAGE = 'en';
const FALLBACK_TIME_ZONE = 'Europe/Paris';
const UNSUBSCRIBE_PATH = '/webhook/unsubscribe';
const LABELS = {
  fr: { read: "Lire l'article", footer: 'Vous recevez cette newsletter car vous êtes inscrit.', unsubscribe: 'Se désinscrire', chatHint: 'Vous pouvez aussi écrire « désinscription » au chatbot.' },
  en: { read: 'Read the article', footer: 'You receive this newsletter because you signed up.', unsubscribe: 'Unsubscribe', chatHint: 'You can also write "unsubscribe" to the chatbot.' },
};

function getLanguage(user) {
  return SUPPORTED_LANGUAGES.includes(user.language) ? user.language : DEFAULT_LANGUAGE;
}

function escapeHtml(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function toSafeUrl(url) {
  return /^https?:\/\//i.test(url || '') ? url : '#';
}

function buildUnsubscribeUrl(publicUrl, userId, signature) {
  if (!publicUrl) {
    throw new Error('Missing public_url in the settings table: run the Setup DB workflow.');
  }
  const baseUrl = publicUrl.replace(/\/+$/, '');
  return `${baseUrl}${UNSUBSCRIBE_PATH}?user=${encodeURIComponent(userId)}&sig=${encodeURIComponent(signature)}`;
}

function getId(article) {
  return article.id;
}

function mergeAiTextIntoArticles(articles, aiItems) {
  const articlesById = new Map();
  for (const article of articles) {
    articlesById.set(article.id, article);
  }

  const aiTextById = new Map();
  for (const aiItem of aiItems) {
    if (articlesById.has(aiItem.id)) {
      aiTextById.set(aiItem.id, aiItem);
    }
  }

  const orderedIds = [...aiTextById.keys()];
  for (const article of articles) {
    if (!aiTextById.has(article.id)) {
      orderedIds.push(article.id);
    }
  }

  const merged = [];
  for (const id of orderedIds) {
    const article = articlesById.get(id);
    const aiText = aiTextById.get(id);
    merged.push({ ...article, title: aiText?.title || article.title, summary: aiText?.summary || article.summary });
  }
  return merged;
}

function formatDate(language, timeZone) {
  return new Date().toLocaleDateString(language, { weekday: 'long', day: 'numeric', month: 'long', timeZone });
}

function renderArticleCard(article, readLabel) {
  const url = escapeHtml(toSafeUrl(article.url));
  return `
  <tr><td style="padding:0 0 24px 0;">
    <p style="margin:0 0 6px 0;font:600 12px Arial,sans-serif;color:#6b7280;text-transform:uppercase;letter-spacing:.06em;">${escapeHtml(article.source)} · ${escapeHtml(article.categories.split(',').join(' · '))}</p>
    <p style="margin:0 0 8px 0;font:700 18px/1.3 Georgia,serif;color:#111827;"><a href="${url}" style="color:#111827;text-decoration:none;">${escapeHtml(article.title)}</a></p>
    <p style="margin:0 0 10px 0;font:15px/1.55 Arial,sans-serif;color:#374151;">${escapeHtml(article.summary)}</p>
    <a href="${url}" style="font:600 14px Arial,sans-serif;color:#2f5bea;text-decoration:none;">${escapeHtml(readLabel)} →</a>
  </td></tr>`;
}

function renderArticleCards(articles, readLabel) {
  let cards = '';
  for (const article of articles) {
    cards += renderArticleCard(article, readLabel);
  }
  return cards;
}

function renderFooter(labels, unsubscribeUrl) {
  return `${escapeHtml(labels.footer)} <a href="${escapeHtml(unsubscribeUrl)}" style="color:#6b7280;">${escapeHtml(labels.unsubscribe)}</a>. ${escapeHtml(labels.chatHint)}`;
}

function renderHtml({ language, subject, date, intro, cards, footer }) {
  return `<!doctype html>
<html lang="${language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(subject)}</title></head>
<body style="margin:0;padding:0;background:#f3f4f6;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;"><tr><td align="center" style="padding:24px 12px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:8px;">
    <tr><td style="padding:28px 28px 8px 28px;">
      <p style="margin:0;font:700 22px Georgia,serif;color:#2f5bea;">${BRAND_NAME}</p>
      <p style="margin:4px 0 0 0;font:13px Arial,sans-serif;color:#6b7280;">${escapeHtml(date)}</p>
    </td></tr>
    <tr><td style="padding:12px 28px 20px 28px;font:16px/1.55 Arial,sans-serif;color:#111827;">${escapeHtml(intro)}</td></tr>
    <tr><td style="padding:0 28px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${cards}</table></td></tr>
    <tr><td style="padding:16px 28px 28px 28px;border-top:1px solid #e5e7eb;font:12px/1.5 Arial,sans-serif;color:#6b7280;">${footer}</td></tr>
  </table>
</td></tr></table>
</body></html>`;
}

function renderTextEntry(article) {
  return `• ${article.title} (${article.source})\n  ${article.summary}\n  ${toSafeUrl(article.url)}\n`;
}

function renderText({ date, intro, articles, labels, unsubscribeUrl }) {
  return [date, '', intro, '', ...articles.map(renderTextEntry), '—', labels.footer, `${labels.unsubscribe} : ${unsubscribeUrl}`, labels.chatHint].join('\n');
}

const { user, articles } = $('Pick best articles').first().json;
const aiText = $('Write newsletter').first().json.output;
const publicUrl = $('Get public URL').first().json.value;
const signature = $('Sign unsubscribe link').first().json.signature;
const language = getLanguage(user);
const labels = LABELS[language];
const newsletterArticles = mergeAiTextIntoArticles(articles, aiText.items || []);
const date = formatDate(language, user.timezone || FALLBACK_TIME_ZONE);
const unsubscribeUrl = buildUnsubscribeUrl(publicUrl, user.id, signature);

const html = renderHtml({
  language,
  subject: aiText.subject,
  date,
  intro: aiText.intro,
  cards: renderArticleCards(newsletterArticles, labels.read),
  footer: renderFooter(labels, unsubscribeUrl),
});
const text = renderText({ date, intro: aiText.intro, articles: newsletterArticles, labels, unsubscribeUrl });

return [{ json: { user_id: user.id, email: user.email, subject: aiText.subject, html, text, article_ids: newsletterArticles.map(getId), unsubscribe_url: unsubscribeUrl } }];
